import argparse
import os
import json

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--run", required=True, help="Path to the raw run directory")
    args = parser.parse_args()

    # The standalone run_validation.py is primarily for offline analysis of the logs 
    # and validation reports generated by the training and fault scripts.
    val_files = [f for f in os.listdir(args.run) if f.startswith("validation_") and f.endswith(".json")]
    
    if not val_files:
        print(f"No validation reports found in {args.run}")
        return
        
    for val_file in sorted(val_files):
        print(f"\n--- Report: {val_file} ---")
        path = os.path.join(args.run, val_file)
        with open(path, "r") as f:
            results = json.load(f)
            
        for res in results:
            status = res.get("status")
            state_name = res.get("state_name")
            message = res.get("message")
            
            if status == "FAIL":
                print(f"[FAIL] {state_name}: {message}")
            elif status == "PASS":
                print(f"[PASS] {state_name}")
            else:
                print(f"[{status}] {state_name}: {message}")

if __name__ == "__main__":
    main()
